-- Indexes for the reads that load an order's lines and history, and two range CHECKs
-- that turn a unit slip into a refused write. Generated by drizzle-kit, then
-- hand-guarded so a reset Neon branch can replay it.
--
-- Indexes. `order_items(order_id)` and `order_events(order_id)` serve every ticket,
-- receipt and audit read; `order_items(menu_item_id)` serves best-seller reports.
-- `order_item_modifiers(order_item_id)` is NOT added: that table's primary key is
-- `(order_item_id, modifier_option_id)`, whose btree already leads with it.
--
-- CHECKs. `locations.tax_rate_per_100k` is 0..25000 (0 to 25%), and every money column
-- on `orders` stays under 100000000 cents (one million dollars). Both validate the rows
-- already present; the test branch had none outside either range when this was written.
--
-- Idempotent: `IF NOT EXISTS` on the indexes, `duplicate_object` swallowed for the
-- constraints, which have no such clause. Neon branches get reset.
CREATE INDEX IF NOT EXISTS "order_events_order_idx" ON "order_events" USING btree ("order_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "order_items_order_idx" ON "order_items" USING btree ("order_id");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "order_items_menu_item_idx" ON "order_items" USING btree ("menu_item_id");--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "locations" ADD CONSTRAINT "locations_tax_rate_range" CHECK ("locations"."tax_rate_per_100k" BETWEEN 0 AND 25000);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "orders" ADD CONSTRAINT "orders_money_cap" CHECK (
    "orders"."subtotal_cents" < 100000000 AND "orders"."tax_cents" < 100000000 AND "orders"."tip_cents" < 100000000
    AND "orders"."delivery_fee_cents" < 100000000 AND "orders"."discount_cents" < 100000000 AND "orders"."total_cents" < 100000000
  );
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;
